function transform (message, context) {

  var headers = Object.keys(message.payload);
  var vals    = Object.values(message.payload);

  vals = vals.map(String);

  if (context.quoteStrings) {
    headers = headers.map(v => v.replaceAll('"', '""')).map(v => `"${v}"`);
    vals    = vals.map(v => v.replaceAll('"', '""')).map(v => `"${v}"`);
  }

  switch (context.delimiter) {
    case 'tab':
      vals             = vals.join('\t');
      context.headers  = headers.join('\t');
      break;
    case 'pipe':
      vals             = vals.join('|');
      context.headers  = headers.join('|');
      break;
    case 'comma':
    default:
      vals             = vals.join(',');
      context.headers  = headers.join(',');
      break;
  }

  message.payload = vals;
  return message;
}

function transform (message, context) {

  if (context.includeHeaders) {
    message.payload = Array.prototype.concat(context.headers, message.payload);
  }

  message.payload = message.payload.join('\r\n');

  // Build date-stamped remote path: <sftpPath>/MU_Students_YYYYMMDD.csv
  var now   = new Date();
  var stamp = String(now.getFullYear())
            + String(now.getMonth() + 1).padStart(2, '0')
            + String(now.getDate()).padStart(2, '0');
  var base  = context.maxientSftpPath.replace(/\/?$/, '/');
  context.resolvedFileName = base + 'MU_Students_' + stamp + '.csv';

  return message;
}
